    C=[("我信神，全能的父，创造天地的主","徒4:24；徒14:15；徒17:24"),("我主耶稣基督，神的独生子","徒2:36；徒9:20；徒13:33"),("从童贞女马利亚所生","徒1:14（耶稣的母亲马利亚）；路1:35"),("在本丢·彼拉多手下受难","徒3:13；徒4:27；徒13:28"),("被钉十字架，受死，被埋葬","徒2:23；徒5:30；徒13:29"),
       ("第三天从死里复活","徒2:24,32；徒10:40；徒13:30-37"),("升天，坐在全能父神的右边","徒1:9-11；徒2:33-34；徒7:55-56"),("将来必从那里降临，审判活人死人","徒1:11；徒10:42；徒17:31"),("我信圣灵","徒1:8；徒2:4,33；徒5:3-4；徒13:2"),("圣而公之教会；圣徒相通","徒2:42-47；徒4:32；徒9:31；徒20:28"),("罪得赦免","徒2:38；徒10:43；徒13:38；徒26:18"),("身体复活；永生","徒4:2；徒13:48；徒17:31-32；徒24:15")]
    b.append('<h2 id="c4">五、信经条款与使徒行传</h2><p class="note">使徒信经的每一条，几乎都能在使徒行传的讲道中找到：信经就是“使徒的教训”（徒2:42）的摘要。</p><div class="tbl"><table><thead><tr><th>使徒信经条款</th><th>使徒行传根据</th></tr></thead><tbody>'+"".join(f'<tr><td>{esc(a)}</td><td>{md(c)}</td></tr>' for a,c in C)+'</tbody></table></div>')
    b.append('<p>海德堡要理问答第 22–23 问说明：基督徒必须相信的福音应许，正是《使徒信经》所总结的内容：</p>'+cq(("hc",22))+cq(("hc",23)))
    b.append('<h2 id="c5">六、加分：三项联合信条（Three Forms of Unity）比较</h2>')
    F=[("年代","1563（德国海德堡）","1561（低地国家，1619 多特会议修订）","1618–1619（多特会议）"),("作者","乌尔西努、俄利维亚努等，腓特烈三世委托","圭多·德·布雷（1567 殉道）","国际改革宗会议（荷兰及各国代表）"),
       ("体裁","129 问答，分 52 个主日","37 条信条","五项教义：正面条文 + 驳斥错谬"),("主线","安慰：罪与愁苦 → 救赎 → 感恩","信仰全景：神 → 圣经 → 创造 → 罪 → 基督 → 救恩 → 教会 → 国家 → 末世","恩典的主权：拣选 → 基督的死 → 败坏与归正 → 坚忍"),
       ("回答的问题","我在生在死唯一的安慰是什么？","改革宗信徒信什么？我们不是叛乱者","救恩是神的工作，还是人自由意志的合作？"),("针对","罗马教会的弥撒与功德；路德宗内部争论","罗马教会的逼迫；重洗派的过激","阿明尼乌派（抗辩派）五点"),
       ("用途","教导儿童、主日下午要理问答讲道","教会信仰的公开宣言","教牧安慰：确据与谦卑"),("与使徒行传","第 65 问：信心藉讲道而生（徒16:14）；第 74 问：儿女同在约中（徒2:39）","第 30–32 条：教会职分与治理（徒6；14:23；15；20:28）；第 36 条：国家（徒5:29）","第一项：拣选（徒13:48）；第三四项：有效呼召（徒16:14）；第五项：坚忍（徒14:22）")]
    b.append('<div class="tbl"><table class="cmp"><thead><tr><th>维度</th><th>📘 海德堡要理问答</th><th>📗 比利时信条</th><th>📕 多特信经</th></tr></thead><tbody>'+"".join(f'<tr><td><b>{a}</b></td><td>{c}</td><td>{d}</td><td>{e}</td></tr>' for a,c,d,e in F)+'</tbody></table></div>')
